95		template <class PAYLOAD>
96		static string ExcessValuesException(const case_insensitive_map_t<idx_t> &parameters,
97		                                    case_insensitive_map_t<PAYLOAD> &values) {
98			// Too many values
99			set<string> excess_set;
100			for (auto &pair : values) {
101				auto &name = pair.first;
102				if (!parameters.count(name)) {
103					excess_set.insert(name);
104				}
105			}
106			vector<string> excess_values;
107			for (auto &val : excess_set) {
108				excess_values.push_back(val);
109			}
110			return StringUtil::Format("Parameter argument/count mismatch, identifiers of the excess parameters: %s",
111			                          StringUtil::Join(excess_values, ", "));
112		}
113	
114		template <class PAYLOAD>
115		static string MissingValuesException(const case_insensitive_map_t<idx_t> &parameters,
116		                                     case_insensitive_map_t<PAYLOAD> &values) {
117			// Missing values
118			set<string> missing_set;
119			for (auto &pair : parameters) {
120				auto &name = pair.first;
121				if (!values.count(name)) {
122					missing_set.insert(name);
123				}
124			}
125			vector<string> missing_values;
126			for (auto &val : missing_set) {
127				missing_values.push_back(val);
128			}
129			return StringUtil::Format("Values were not provided for the following prepared statement parameters: %s",
130			                          StringUtil::Join(missing_values, ", "));
131		}
